import subprocess
result = subprocess.run(['strings', '/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat'], capture_output=True, text=True)
lines = result.stdout.split('\n')

# Find all strings that might be passwords (20-30 chars, mostly alphanumeric)
candidates = []
for line in lines:
    if 20 <= len(line) <= 26 and line.replace('=', '').replace('-', '').replace('_', '').isalnum():
        if line.startswith('8XD') or line.endswith('W54'):
            candidates.append(line)

for c in candidates:
    print(f"{len(c):2d}: {c}")
