arguments.command:
python3 << 'EOF'
import subprocess

# Get all strings from the binary file
result = subprocess.run(['strings', '/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat'], 
                       capture_output=True, text=True)
strings_list = result.stdout.split('\n')

# Search for anything with 8XD or W54
print("All strings containing '8XD':")
for s in strings_list:
    if '8XD' in s:
        print(f"  '{s}' (len={len(s)})")

print("\nAll strings containing 'W54':")
for s in strings_list:
    if 'W54' in s:
        print(f"  '{s}' (len={len(s)})")

print("\nAll strings that look like passwords (10-30 chars, mostly alphanumeric + =-):")
for s in strings_list:
    if 10 <= len(s) <= 30:
        alpha_count = sum(1 for c in s if c.isalnum())
        if alpha_count / len(s) > 0.7:  # >70% alphanumeric
            if any(c in 'PASSWORD' for c in s.upper()):
                print(f"  '{s}' (len={len(s)})")
EOF

